240:             "registry_name": {"type": ["string", "null"],
241:               "description": "model: 该依赖的规范/注册表包名（PyPI/npm/Maven artifact/crate；或 CMake find_package 的真实包名），当 `name` 是别名/接口名/缩写时填它，便于按名关联到已分析库。不确定则 null。"},
242:             "source_repo": {"type": ["string", "null"],
243:               "description": "model (best-effort): 该依赖的上游源码仓库 URL（github/gitlab/gitee/自托管均可）。是把依赖关联到已分析库的最强键——能从 manifest/lock/已知常识判断就填，含 `find_package(PNG)`→glennrp/libpng 这类名≠仓的情形。不确定则 null。"},
244:             "import_names": {"type": "array", "items": {"type": "string"},
245:               "description": "model: 实际 import 名（如依赖 Pillow → 代码里 import PIL）。无则省略。"},
246:             "aliases": {"type": "array", "items": {"type": "string"},
247:               "description": "model: 该依赖的其它已知名称/拼写。无则省略。"},
